package com.bank.analytics.service;

import java.util.logging.Logger;

// Counts structurally unique BSTs over 1..n using the Catalan DP recurrence.
public class BstCountService {
    private static final Logger log = Logger.getLogger(BstCountService.class.getName());

    public long countShapes(int n) {
        long[] count = new long[n + 1];
        count[0] = 1;              // empty tree: one arrangement
        if (n >= 1) {
            count[1] = 1;          // single value: one arrangement
        }
        for (int k = 2; k <= n; k++) {
            for (int root = 1; root <= k; root++) {
                // left has root-1 values, right has k-root values
                count[k] += count[root - 1] * count[k - root];
            }
            int kk = k;
            log.fine(() -> "count[" + kk + "] = " + count[kk]);
        }
        long answer = count[n];
        log.info(() -> "Structurally unique BSTs for n=" + n + " = " + answer);
        return answer;
    }
}
