package com.bank.analytics;

import com.bank.analytics.service.BstCountService;
import java.util.logging.Logger;

public class BstCountApplication {
    private static final Logger log = Logger.getLogger(BstCountApplication.class.getName());

    public static void main(String[] args) {
        BstCountService service = new BstCountService();
        for (int n = 1; n <= 5; n++) {
            log.info("NBI tier BST shape count for n=" + n + ": " + service.countShapes(n));
        }
    }
}
